package O1;
import android.app.*;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.lang.reflect.*;
import java.util.*;

/** Isolated host files and in-memory HTTPS routes. No Android runtime or device caches. */
public class NativeDeliveryTest {
 static int checks,requests;static boolean offline;static Map<String,byte[]> routes=new HashMap<>();static List<String> requested=new ArrayList<>();static Path assets,files;
 static final String URLROOT="https://github.com/"+DeliveryPolicy.REPO+"/releases/download/fixture-v203/";
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
 static class Conn extends HttpURLConnection {
  final byte[] bytes;Conn(URL u){super(u);requests++;requested.add(u.toString());bytes=routes.get(u.toString());}public void connect(){}public void disconnect(){}public boolean usingProxy(){return false;}
  long[] range(){String s=getRequestProperty("Range");if(s==null)return null;String[] p=s.substring(6).split("-");return new long[]{Long.parseLong(p[0]),Long.parseLong(p[1])};}
  public int getResponseCode()throws IOException{if(offline)throw new IOException("fixture offline");return bytes==null?404:range()==null?200:206;}
  public String getHeaderField(String key){long[] r=range();if(r!=null&&key.equals("Content-Range"))return "bytes "+r[0]+"-"+r[1]+"/"+bytes.length;return null;}
  public InputStream getInputStream(){long[] r=range();return new ByteArrayInputStream(r==null?bytes:Arrays.copyOfRange(bytes,(int)r[0],(int)r[1]+1));}
 }
 static byte[] bytes(String s)throws Exception{return s.getBytes("UTF-8");}
 static String row(String path,String body)throws Exception{byte[] b=bytes(body);String url=URLROOT+DeliveryPolicy.hash(b)+".bin";routes.put(url,b);return path+"\t"+DeliveryPolicy.hash(b)+"\t"+b.length+"\t"+url+"\t0\t"+b.length+"\t0\t"+b.length+"\n";}
 static byte[] catalog(String rows)throws Exception{return bytes("ffbe-content-v1\n"+rows);}
 static void clear(Class<?> cls,String name,Object value)throws Exception{Field f=cls.getDeclaredField(name);f.setAccessible(true);f.set(null,value);}
 static void reset()throws Exception{
  for(String s:new String[]{"entries","baseline","candidate","byHash"})clear(ExtraContent.class,s,null);Field f=ExtraContent.class.getDeclaredField("verified");f.setAccessible(true);((Map<?,?>)f.get(null)).clear();
  for(String s:new String[]{"config","bundledRoot","bundledContent","bundledBase","activeRootHash","roots","bootPaths","pending","activeRevision","pendingCatalog"})clear(GameAssets.class,s,null);clear(GameAssets.class,"checked",false);clear(GameAssets.class,"bootReady",false);clear(GameAssets.class,"highest",0L);
 }
 static String spec(byte[] b,String name)throws Exception{String h=DeliveryPolicy.hash(b),url=URLROOT+name+"-"+h+".tsv";routes.put(url,b);return "{\"sha256\":\""+h+"\",\"bytes\":"+b.length+",\"url\":\""+url+"\"}";}
 static String assetRows(String namespace,long v,byte[] catalog)throws Exception{StringBuilder out=new StringBuilder();for(ExtraContent.Entry e:ExtraContent.parseCatalog(catalog).values()){if(out.length()>0)out.append(',');out.append("{\"namespace\":\"").append(namespace).append("\",\"path\":\"").append(e.path).append("\",\"sha256\":\"").append(e.hash).append("\",\"version\":").append(v).append(",\"bytes\":").append(e.size).append(",\"phase\":\"").append(e.path.startsWith("side_stories/")?"game":"boot").append("\",\"transport\":{\"url\":\"").append(e.url).append("\",\"offset\":").append(e.offset).append(",\"wire_bytes\":").append(e.wireSize).append(",\"method\":").append(e.method).append(",\"source_bytes\":").append(e.sourceSize).append("}}");}return out.toString();}
 static byte[] descriptor(long v,byte[] root,byte[] content,byte[] base)throws Exception{return bytes("{\"schema\":\"ffbe-asset-manifest-v1\",\"channel\":\"beta\",\"package\":\""+DeliveryPolicy.PACKAGE+"\",\"signing_certificate_sha256\":\""+DeliveryPolicy.SIGNER+"\",\"asset_version\":"+v+",\"APK_min_version\":203,\"engine_compat\":\""+DeliveryPolicy.ENGINE+"\",\"root_catalog\":"+spec(root,"root")+",\"content_catalog\":"+spec(content,"content")+",\"base_catalog\":"+spec(base,"base")+",\"assets\":["+assetRows("root",v,root)+","+assetRows("content",v,content)+"]}");}
 static void downloadAll()throws Exception{for(ExtraContent.Entry e:ExtraContent.missing())ExtraContent.download(e);}
 public static void main(String[] args)throws Exception{
  Path fixture=Files.createTempDirectory(Paths.get(args[0]),"native-delivery-");assets=Files.createDirectories(fixture.resolve("assets"));files=Files.createDirectories(fixture.resolve("files"));ActivityThread.app=new Application(files.toFile(),assets.toFile());
  URL.setURLStreamHandlerFactory(p->p.equals("https")?new URLStreamHandler(){protected URLConnection openConnection(URL u){return new Conn(u);}}:null);ResumableTransfer.delay=ms->{};
  GameAssets.linker=new GameAssets.Linker(){public boolean same(File t,File s)throws Exception{return Files.isSameFile(t.toPath(),s.toPath());}public void create(File t,File s)throws Exception{Files.createLink(t.toPath(),s.toPath());}};
  byte[] root=catalog(row("cpk/root.cpk","boot-pack")+row("font/root.ttf","boot-font")+row("side_stories/event.dat","roster-old"));byte[] content=catalog(row("side_stories/event.dat","roster-old")+row("battle/alias.dat","roster-old")+row("side_stories/r2/a.dat","another-event"));byte[] base=bytes("ffbe-base-v1\n");
  Files.write(assets.resolve("root_delivery.tsv"),root);Files.write(assets.resolve("content_delivery.tsv"),content);Files.write(assets.resolve("base_delivery.tsv"),base);Files.write(assets.resolve("delivery_release.tsv"),bytes("ffbe-delivery-release-v1\nbeta\t203\t203\t"+DeliveryPolicy.hash(root)+"\t"+DeliveryPolicy.hash(content)+"\t"+DeliveryPolicy.metadataURL("beta","patch_version.json")+"\t"+DeliveryPolicy.metadataURL("beta","manifest.json")+"\n"));
  Files.write(assets.resolve("game_asset_manifest.json"),descriptor(203,root,content,base));
  ExtraContent.load();check(requests==0&&ExtraContent.current().size()==5,"bundled metadata union loads with zero network requests");check(ExtraContent.missingBoot().size()==2,"only core boot assets needed before native UI");ContentDownloader.downloadBootAssets(null);check(GameAssets.bootReady()&&requests==2,"existing per-file transfer prepares boot filesystem");check(ExtraContent.missing().size()==2,"game data remains for native on-demand phase, aliases deduplicated");
  try(InputStream in=GameAssets.open(ActivityThread.app.getAssets(),"cpk/root.cpk")){check(Arrays.equals(GameAssets.read(in,1024),bytes("boot-pack")),"Java asset reads verified file cache");}check(Arrays.asList(GameAssets.list(ActivityThread.app.getAssets(),"cpk")).contains("root.cpk"),"Java asset directory exposes external game tree");
  check(GameAssets.webURL("file:///android_asset/cpk/root.cpk#frame").startsWith("file:")&&!GameAssets.webURL("file:///android_asset/cpk/root.cpk#frame").contains("android_asset")&&GameAssets.webURL("file:///android_asset/cpk/root.cpk#frame").endsWith("#frame"),"external WebView file URL preserves fragments");check(GameAssets.webURL("file:///android_asset/cpk/").contains("/tree/cpk/"),"WebView base directory points to verified tree");check(GameAssets.webURL("https://example.test/page").equals("https://example.test/page"),"unrelated network WebView URLs preserved");
  downloadAll();GameAssets.prepareCurrentTree();check(ExtraContent.missing().isEmpty()&&requests==4,"all game data ready via four unique file hashes");
  requests=0;offline=true;reset();ExtraContent.load();ContentDownloader.downloadBootAssets(null);check(ExtraContent.missing().isEmpty()&&requests==0,"cold offline reuse verifies cached graph with zero transfers");offline=false;
  byte[] newerRoot=catalog(row("cpk/root.cpk","boot-pack")+row("font/root.ttf","boot-font")+row("side_stories/event.dat","roster-new"));byte[] newerContent=catalog(row("side_stories/event.dat","roster-new")+row("battle/alias.dat","roster-old")+row("side_stories/r2/a.dat","another-event"));byte[] next=descriptor(204,newerRoot,newerContent,base);routes.put(DeliveryPolicy.metadataURL("beta","manifest.json"),next);
  ExtraContent.checkHostedUpdate();check(ExtraContent.current().get("side_stories/event.dat").hash.equals(DeliveryPolicy.hash(bytes("roster-old"))),"higher manifest never swaps current native handles");check(ExtraContent.missing().size()==1,"only changed hash selected after compatible update");int before=requests;downloadAll();check(requests==before+1,"changed-only update fetches exactly one asset");check(!ExtraContent.activateHostedUpdate(),"verified update stages without hot activation");
  reset();ExtraContent.load();check(ExtraContent.current().get("side_stories/event.dat").hash.equals(DeliveryPolicy.hash(bytes("roster-new")))&&ExtraContent.missing().isEmpty(),"next cold launch adopts verified higher graph");
  Path state=files.resolve("game_assets/releases/"+DeliveryPolicy.ENGINE+"/beta");Path rootCatalog=state.resolve(DeliveryPolicy.hash(newerRoot)+".tsv");Files.delete(rootCatalog);requests=0;reset();ExtraContent.load();check(requests==1&&Files.isRegularFile(rootCatalog)&&ExtraContent.current().get("side_stories/event.dat").hash.equals(DeliveryPolicy.hash(bytes("roster-new"))),"missing active catalog repaired by pinned URL without roster rollback");
  byte[] bad=Files.readAllBytes(rootCatalog);bad[bad.length-2]^=1;Files.write(rootCatalog,bad);requests=0;reset();ExtraContent.load();check(requests==1&&Arrays.equals(Files.readAllBytes(rootCatalog),newerRoot),"same-length corrupt active catalog quarantined and repaired");
  Path activeDescriptor=state.resolve(DeliveryPolicy.hash(next)+".json");byte[] exact=Files.readAllBytes(activeDescriptor);Files.write(activeDescriptor,bytes(new String(exact,"UTF-8").replace("\"asset_version\":204","\"asset_version\":205")));reset();boolean descriptorBlocked=false;try{ExtraContent.load();}catch(IOException wrong){descriptorBlocked=wrong.getMessage().contains("Active asset metadata is damaged");}check(descriptorBlocked,"changed selected descriptor fails closed without older roster fallback");Files.write(activeDescriptor,exact);reset();ExtraContent.load();
  Files.delete(rootCatalog);offline=true;reset();boolean blocked=false;try{ExtraContent.load();}catch(IOException damaged){blocked=damaged.getMessage().contains("Active asset metadata is damaged");}check(blocked,"offline missing active metadata fails closed with repair message");offline=false;reset();ExtraContent.load();
  ExtraContent.Entry changed=ExtraContent.current().get("side_stories/event.dat");Path cached=ExtraContent.target(changed).toPath();byte[] corrupt=Files.readAllBytes(cached);corrupt[0]^=1;Files.write(cached,corrupt);reset();ExtraContent.load();check(ExtraContent.missing().size()==1,"cold SHA check detects same-length corrupt game cache");requests=0;downloadAll();check(requests==1&&ExtraContent.missing().isEmpty(),"damaged current game object repaired incrementally");
  // Future candidate plus missing current bytes must include both, avoiding a native retry loop.
  ExtraContent.Entry oldEvent=ExtraContent.current().get("side_stories/r2/a.dat");Path current=ExtraContent.target(oldEvent).toPath();Files.delete(current);Files.delete(files.resolve("game_assets/hash_index/"+oldEvent.hash));reset();ExtraContent.load();byte[] thirdRoot=catalog(row("cpk/root.cpk","boot-pack")+row("font/root.ttf","boot-font")+row("side_stories/event.dat","roster-third"));byte[] thirdContent=catalog(row("side_stories/event.dat","roster-third")+row("battle/alias.dat","roster-old")+row("side_stories/r2/a.dat","changed-event"));routes.put(DeliveryPolicy.metadataURL("beta","manifest.json"),descriptor(205,thirdRoot,thirdContent,base));ExtraContent.checkHostedUpdate();check(ExtraContent.missing().size()==3,"future changes plus missing current assets retained in one queue");downloadAll();GameAssets.prepareCurrentTree();check(ExtraContent.missing().isEmpty(),"future staging does not strand current native tree");
  Map<String,ExtraContent.Entry> removed=new LinkedHashMap<>(ExtraContent.current());removed.remove("cpk/root.cpk");boolean rejected=false;try{GameAssets.validateGraph(removed,ExtraContent.current());}catch(IOException ok){rejected=true;}check(rejected,"future manifest cannot silently remove preserved data");
  System.out.println("PASSED "+checks+" native-delivery host cache/transition checks (hardlinks simulate public Android symlinks; no device runtime)");
 }
}
